565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2", "id": "line-2", "locator": {"line": 2}, "text": "Two paths reach the same detector, each with a complex amplitude.", "stale": false}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3", "id": "line-3", "locator": {"line": 3}, "text": "The total amplitude is the sum of the path amplitudes.", "stale": false}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4", "id": "line-4", "locator": {"line": 4}, "text": "The probability is the squared magnitude of the total amplitude.", "stale": false}]}, "route": [{"id": "paths", "title": "Adding path amplitudes"}, {"id": "states", "title": "States and global phase", "prerequisites": ["paths"]}, {"id": "outcomes", "title": "Measurement outcomes", "prerequisites": ["states"]}], "session": {"position": {"concept_id": "paths", "goal": "Predict interference", "next_step": "Start the lesson", "progress": ""}, "active_branch": null, "due_explanations": [], "unanswered_questions": [], "recent_interactions": [{"id": "stream-user:54b45424-fdcd-481c-90a1-6f3c151da4db", "role": "user", "text": "Teach this section step by step, starting with the first step.", "concept_id": "paths", "source_refs": [{"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 1}, {"id": "stream:54b45424-fdcd-481c-90a1-6f3c151da4db", "role": "assistant", "text": "## Path amplitudes\n\nEach path carries a complex amplitude $a$ or $b$.\n<course-memory>{\"entries\": [{\"kind\": \"taught_term\", \"text\": \"amplitude\"}, {\"kind\": \"preference\", \"text\": \"Short steps with one formula each\"}], \"cleared\": []}</course-memory>\n<lesson-step>{\"title\": \"Path amplitudes\", \"remaining\": [{\"title\": \"Adding amplitudes\"}], \"check\": {\"idea\": \"What does a path carry?\", \"question\": \"What does a path carry?\", \"correct\": 0, \"options\": [{\"text\": \"A complex amplitude\", \"explanation\": \"Each path contributes an amplitude.\"}, {\"text\": \"A probability\", \"explanation\": \"Probabilities come only after adding.\"}]}}</lesson-step>", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 2}, {"id": "check-answer:54b45424-fdcd-481c-90a1-6f3c151da4db", "role": "user", "text": "Check question: What does a path carry?\nAnswer: A probability", "concept_id": "paths", "kind": "check_answer", "supplied_source_refs": [], "source_refs": [], "source_context_concept_id": "paths", "sequence": 3}, {"id": "stream-user:step:1f5674e1-08f9-4142-8fcc-7d59dc8d87e7", "role": "user", "text": "Continue with the next step.", "concept_id": "paths", "source_refs": [{"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 4}, {"id": "stream:step:1f5674e1-08f9-4142-8fcc-7d59dc8d87e7", "role": "assistant", "text": "## Adding amplitudes\n\n$$P = |a + b|^2 = |a|^2 + |b|^2 + 2\\,\\mathrm{Re}(a^* b)$$\n<course-memory>{\"entries\": [{\"kind\": \"taught_term\", \"text\": \"interference term\"}], \"cleared\": []}</course-memory>\n<lesson-step>{\"remaining\": []}</lesson-step>", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 5}]}, "language": "en", "chapters": [{"id": "superposition", "title": "Superposition", "concept_ids": ["paths", "states"]}, {"id": "measurement", "title": "Measurement", "concept_ids": ["outcomes"]}], "learner_profile": {"goal": "Understand interference and measurement", "depth": "standard", "prerequisites": [{"topic": "Complex numbers", "level": "some", "check": "Multiplied two complex numbers"}], "focus": "Problem solving"}, "course_memory": {"preferences": ["Worked example before each new idea"], "taught_terms": [{"term": "amplitude", "concept_id": "paths"}]}, "widgets": ["plot"]}, "attempt": 1, "status": "completed", "text": "{\"questions\": [{\"question\": \"Two paths have amplitudes $1/2$ and $e^{i\\\\phi}/2$.\", \"parts\": [{\"label\": \"(a)\", \"text\": \"Find $P(\\\\phi)$.\"}, {\"label\": \"(b)\", \"text\": \"When is it zero?\"}], \"origin\": \"self_created\", \"source_refs\": []}]}", "final_text": "{\"questions\": [{\"question\": \"Two paths have amplitudes $1/2$ and $e^{i\\\\phi}/2$.\", \"parts\": [{\"label\": \"(a)\", \"text\": \"Find $P(\\\\phi)$.\"}, {\"label\": \"(b)\", \"text\": \"When is it zero?\"}], \"origin\": \"self_created\", \"source_refs\": []}]}", "sequence": 3, "started_at": 1795105864.3128998, "metrics": {"first_delta_s": 0.003534078598022461, "full_s": 0.003891468048095703, "save_s": 8.70730000315234e-05}, "attempts": [], "resume_requests": []}');
