INSERT INTO "documents" VALUES('practice_tasks','practice-246b5952-7b8c-4239-8463-9e8d723e5ccd:0','{"id": "practice-246b5952-7b8c-4239-8463-9e8d723e5ccd:0", "concept_id": "paths", "question": "Two paths have amplitudes $1/2$ and $e^{i\\phi}/2$.", "origin": "self_created", "source_refs": [], "status": "attempted", "history": [{"action": "hint", "feedback": "Expand $|z|^2 = z^* z$ first."}, {"action": "assess", "feedback": "Part (a) is right; check the sign in (b).", "outcome": "needs_work", "parts": ["correct", "not_yet"], "evidence_id": "practice-evidence:practice-6e28ca2b-1417-4a5b-bdd8-47740158ec58", "kind": "needs_work", "answer": "(a) P = (1 + cos phi)/2. (b) phi = 0."}, {"action": "assess", "feedback": "Part (a) is right; check the sign in (b).", "outcome": "passed", "parts": ["correct", "correct"], "evidence_id": "practice-evidence:practice-02d711b1-1a5a-44ce-95d2-5f73cc520ea2", "kind": "hinted", "answer": "(a) P = (1 + cos phi)/2. (b) phi = pi."}], "created_at": 1795105864.3172104, "parts": [{"label": "(a)", "text": "Find $P(\\phi)$."}, {"label": "(b)", "text": "When is it zero?"}]}');
