INSERT INTO "documents" VALUES('streams','consolidation-paths','{"record_user": false, "id": "consolidation-paths", "concept_id": "paths", "prompt": "Internal memory task: consolidate the course memory at the end of a section.", "channel": "consolidation", "language": "en", "source_refs": [{"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "prompt_snapshot": {"context": {"concept": {"id": "paths", "title": "Adding path amplitudes", "objective": "Predict interference from two amplitudes", "links": [{"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "exercises": [{"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4", "question": "Find the probability for equal amplitudes.", "required_concepts": ["paths"]}]}, "chapter": {"id": "superposition", "title": "Superposition", "concept_ids": ["paths", "states"], "index": 0, "total": 2}, "position": {"concept_id": "states", "goal": "Understand States and global phase", "next_step": "Begin teaching this section", "progress": ""}, "prerequisites": [], "next_concept_id": "states", "sources": [{"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2", "id": "line-2", "locator": {"line": 2}, "text": "Two paths reach the same detector, each with a complex amplitude.", "stale": false}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3", "id": "line-3", "locator": {"line": 3}, "text": "The total amplitude is the sum of the path amplitudes.", "stale": false}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4", "id": "line-4", "locator": {"line": 4}, "text": "The probability is the squared magnitude of the total amplitude.", "stale": false}]}, "route": [{"id": "paths", "title": "Adding path amplitudes"}, {"id": "states", "title": "States and global phase", "prerequisites": ["paths"]}, {"id": "outcomes", "title": "Measurement outcomes", "prerequisites": ["states"]}], "session": {"position": {"concept_id": "states", "goal": "Understand States and global phase", "next_step": "Begin teaching this section", "progress": ""}, "active_branch": null, "due_explanations": [], "unanswered_questions": [], "recent_interactions": [{"id": "stream:branch:cross-term", "role": "assistant", "text": "Because $|z|^2 = z^* z$, the cross terms give $2\\,\\mathrm{Re}(a^* b)$.\n<teaching-decision>{\"depth\": \"short\", \"category\": \"local\", \"rationale\": \"Local algebra\", \"suggest_supplement\": false, \"supplement_goal\": \"\"}</teaching-decision>\n<course-memory>{\"entries\": [{\"kind\": \"taught_term\", \"text\": \"complex conjugate\"}], \"cleared\": []}</course-memory>", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 8}, {"id": "stream-user:reply:cross-term:e6505da2-8f8b-4521-b54a-44e666e324fc", "role": "user", "text": "And when both amplitudes are real?", "concept_id": "paths", "source_refs": [{"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 9}, {"id": "stream:reply:cross-term:e6505da2-8f8b-4521-b54a-44e666e324fc", "role": "assistant", "text": "## Lesson\n\nA state is a normalized vector.\n<lesson-step>{\"remaining\": []}</lesson-step>", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 10}, {"id": "stream:practice-90eb59d8-c7c1-43c3-8b9e-29f155ba98d3", "role": "assistant", "text": "{\"feedback\": \"Expand $|z|^2 = z^* z$ first.\"}", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 11}, {"id": "practice-feedback:practice-90eb59d8-c7c1-43c3-8b9e-29f155ba98d3", "role": "assistant", "text": "Expand $|z|^2 = z^* z$ first.", "concept_id": "paths", "supplied_source_refs": [], "source_refs": [], "source_context_concept_id": "paths", "sequence": 12}, {"id": "practice-answer:practice-6e28ca2b-1417-4a5b-bdd8-47740158ec58", "role": "user", "text": "(a) P = (1 + cos phi)/2. (b) phi = 0.", "concept_id": "paths", "source_refs": [{"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 13}, {"id": "stream:practice-6e28ca2b-1417-4a5b-bdd8-47740158ec58", "role": "assistant", "text": "{\"feedback\": \"Part (a) is right; check the sign in (b).\", \"parts\": [\"correct\", \"not_yet\"], \"memory\": {\"entries\": [{\"kind\": \"difficulty\", \"text\": \"Signs of phases\"}]}}", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-5b1d264ea9ff565533dd77c1", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 14}, {"id": "practice-feedback:practice-6e28ca